python3 -c "
import sys, json
lines = sys.stdin.readlines()
print(f'Total events: {len(lines)}')
if lines:
    # show last 10
    for l in lines[-10:]:
        try:
            e = json.loads(l)
            print(e.get('epic_id','?'), e.get('phase','?'), e.get('event_type','?'), e.get('status','?'))
        except:
            print(l.strip())
"

